sys_script.script:
(function executeRule(current, previous /*null when async*/) {

	// Add your code here
	// Only run when the completed field changes
    if (current.completed.changes()) {

        // Get the parent Weekly Action record
        var parent = current.weekly_action.getRefRecord();
        if (!parent.isValidRecord()) {
            return;
        }

        // If the current record was set to false → clear parent ACD immediately
        if (current.completed == false) {
			parent.completed = false;
            parent.actual_completion_date = '';
            parent.update();
            return;
        }

        // If the current record was set to true → check if all siblings are completed
        var daily = new GlideRecord('x_942105_12_week_y_daily_tactic');  
        daily.addQuery('weekly_action', parent.sys_id);
        daily.addQuery('completed', false);
        daily.query();

        // If any daily action is still incomplete → do nothing
        if (daily.next()) {
            return;
        }

        // All daily actions are completed → set parent ACD to today
		parent.completed = true;
        parent.actual_completion_date = new GlideDateTime();
        parent.update();
    }

})(current, previous);
